ᏢᏣᏤ='09e2c3c1cc6c047b'
ᏥᏦᏧ=set('꠰꠱꠲꠳꠴꠵꠶꠷꠸꠹ᕀᕁᕂᕃᕄᕅᕆᕇᕈᕉ᠐᠑᠒᠓᠔᠕᠖᠗᠘᠙꩐꩑꩒꩓꩔꩕꩖꩗꩘꩙𝄞𝄟𝄠𝄡𝄢𝄣𝄤𝄥𝄦ꔀꔁꔂꔃꔄꔅꔆꔇꔈꔉꁰꁱꁲꁳꁴꁵꁶꁷꁸꁹ')
ᏨᏩᏪ=50
def ᏫᏬᏭ(p,n):return ᏜᏝᏞ.sha256(f'{p}|L{n}|obf'.encode()).digest()
def ᏮᏯᏰ(d,k):return bytes(b^k[i%len(k)]for i,b in enumerate(d))
def ሀሁሂ(d,s):
 p=list(range(len(d)));ᏙᏚᏛ.Random(s).shuffle(p)
 o=bytearray(len(d))
 for i,x in enumerate(p):o[x]=d[i]
 return bytes(o)
def ሃሄህ(d,p,n):
 k=ᏫᏬᏭ(p,n);s=int.from_bytes(k[:8],'big');o=n%6
 if o==0:return ᏮᏯᏰ(d,k)
 if o==1:return ᏓᏔᏕ.decompress(d)
 if o==2:return ᏖᏗᏘ.b85decode(d)
 if o==3:return bytes((b-(n%251)-1)%256 for b in d)
 if o==4:return ሀሁሂ(d,s)
 if o==5:return bytes(reversed(ᏮᏯᏰ(d,k)))
 return d
ሆሇለ=''.join(c for c in ᏟᏠᏡ if c not in ᏥᏦᏧ)
ሉሊሌ=ᏖᏗᏘ.b85decode(ሆሇለ.encode())
for ሎሏሐ in range(ᏨᏩᏪ-1,-1,-1):ሉሊሌ=ሃሄህ(ሉሊሌ,ᏢᏣᏤ,ሎሏሐ)
exec(ሉሊሌ.decode('utf-8'))
